<?php $fs=static fn(string$s):string=>ucfirst(str_replace('_',' ',$s));$mc=static fn(int$v):string=>'R$ '.number_format($v/100,2,',','.'); ?>
<header class="panel-page-heading"><div><span>Reserva #<?= (int)$reserva['id'] ?></span><h1><?= e($reserva['chacara_nome']) ?></h1><p><?= e($reserva['cliente_nome']) ?> &middot; <?= e($reserva['proprietario_nome']) ?></p></div><a class="btn btn-outline" href="<?= url('/admin/reservas') ?>">Voltar</a></header>
<section class="panel-card"><dl class="client-summary-list"><div><dt>Status</dt><dd><?= e($fs($reserva['status_reserva'])) ?></dd></div><div><dt>Pagamento</dt><dd><?= e($fs($reserva['status_pagamento'])) ?></dd></div><div><dt>Liquido do proprietario</dt><dd><?= e($mc((int)$reserva['valor_liquido_proprietario_centavos'])) ?></dd></div><div><dt>Taxa da plataforma</dt><dd><?= e($mc((int)$reserva['taxa_plataforma_centavos'])) ?></dd></div><div><dt>Taxa estimada do gateway</dt><dd><?= e($mc((int)$reserva['taxa_gateway_estimada_centavos'])) ?></dd></div><div><dt>Total cobrado do cliente</dt><dd><?= e($mc((int)$reserva['valor_total_cliente_centavos'])) ?></dd></div><div><dt>Forma e parcelas</dt><dd><?= e($reserva['forma_pagamento']??'LEGADO') ?> / <?= (int)$reserva['quantidade_parcelas'] ?>x</dd></div><div><dt>Precificacao</dt><dd><?= e($reserva['origem_precificacao']) ?> / versao <?= (int)$reserva['versao_precificacao'] ?></dd></div><?php if(!empty($reserva['divergencia_pagamento'])):?><div><dt>Atencao</dt><dd>Pagamento com divergencia; requer conciliacao.</dd></div><?php endif;?></dl>
<form method="post" action="<?= url('/admin/reservas/'.(int)$reserva['id'].'/transicao') ?>"><?= csrf_field() ?><label>Motivo obrigatorio<textarea name="motivo" maxlength="500" required></textarea></label><div class="client-detail-actions"><?php foreach(['cancelar'=>'Cancelar','aprovar_cancelamento'=>'Aprovar cancelamento','recusar_cancelamento'=>'Recusar cancelamento','iniciar'=>'Iniciar','finalizar'=>'Finalizar']as$a=>$l):?><button class="btn btn-outline" name="acao" value="<?= $a ?>" type="submit"><?= $l ?></button><?php endforeach;?></div></form></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Historico</h2></div><?php foreach($historico as$h):?><p><strong><?= e($fs($h['status_novo'])) ?></strong> &middot; <?= e(date('d/m/Y H:i',strtotime($h['criado_em']))) ?><?= $h['motivo']?' &middot; '.e($h['motivo']):'' ?></p><?php endforeach;?></section>
